const e="Ils portent l’héritage des Dragons sans porter leur couronne.",t="Chronique d'Ikawora",s=["Peuple & Lignée","Héritage Draconique","Codex #PEU-004"],n=[1,4,8],r="Ikawora, Archipels, Vieux Monde",a="Écailles, Traits draconiques, Mémoire ancienne",o="170cm - 200cm",i="120",l="« Dragons errants »",u="DraZun_icone.jpeg",c="Rare",p=[{title:"Présentation",type:"text",content:"Les Dra’Zuun sont un peuple lié à l’ancien héritage draconique. Leur apparence rappelle les Dragons, mais ils ne sont pas responsables de la domination draconique passée. Après la Rébellion, ils durent survivre face au rejet des vainqueurs."},{title:"Le Refuge d'Ikawora",type:"text",content:"Chassés de nombreuses terres après la chute des Dragons, une grande partie des Dra'Zuun trouva refuge auprès des Elfes Umiyori en Ikawora, où ils purent préserver leur culture."},{title:"Culture et Mémoire",type:"text",content:"Leur culture accorde une valeur primordiale à la transmission orale, aux fragments du passé et à la préservation des lignées."},{title:"Relations avec les autres peuples",type:"politique_list_long",content:[{headline:"Amical",title:"Les Elfes Umiyori",content:"Les Umiyori leur ont offert des terres et une protection durable en Ikawora.",color:"#34D399"},{headline:"Méfiance",title:"Les Valm",content:"Longtemps associés à tort aux anciens oppresseurs dragons par les communautés humaines.",color:"#FF7A5C"}]},{title:"Aujourd'hui",type:"text",content:"Ils sont très présents dans les régions maritimes d'Ikawora et sont réputés comme navigateurs, guides et gardiens d'érudition ancienne."},{title:"Secrets",type:"dm-banner",content:"Leur véritable lien avec les Dragons remonte à une époque antérieure à la Rébellion des Valm et recèle des mystères non résolus."}],d={citation:e,citation_author:t,tags:s,link_articles:n,class:"Draconique",repart:r,trait:a,height:o,age:i,surname:l,image:u,statut:c,sections:p};export{i as age,e as citation,t as citation_author,d as default,o as height,u as image,n as link_articles,r as repart,p as sections,c as statut,l as surname,s as tags,a as trait};
